INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62788294', 62788294, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'SEKRETARIAT DPRD', 'Penyediaan Langganan Internet dan TV Kabel', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang (Kota)', 565363200, 'January 2026', 'APBD', 1, 1, '1 Tahun', 'Kebutuhan akan teknologi internet dewasa ini sangatlah diperlukan, mulai dari kebutuhan untuk hiburan sampai berbagai bidang industri tidak terlepas dari penggunaan teknologi internet, untuk itu diperlukan akses internet yang bagus dan handal, sehingga dapat memenuhi kebutuhan akan informasi yang tiap detiknya selalu berkembang. Dengan tersedianya Belanja Berlangganan Internet dan TV Kabel kebutuhan Sekretariat DPRD dan DPRD Kota Tangerang, maka akan memberikan kinerja yang lebih optimal sehingga pelayanan kepada masyarakat dapat terpenuhi dan dapat memperlancar dan juga meningkatkan disiplin agar lebih optimal dalam bekerja. Oleh karena itu, sangat dibutuhkan adanya Belanja Berlangganan Internet dan TV Kabel agar dapat meningkatkan kinerja sehingga disiplin kerja lebih meningkat. Sehubungan dengan hal diatas, Belanja Berlangganan Internet dan TV Kabel bagi anggota DPRD dan Aparatur Sekretariat DPRD Kota Tangerang harus diperhitungkan anggarannya dengan cermat untuk dituangkan kedalam RKA/RDPPA Sekretariat DPRD Kota Tangerang dan dirumuskan serta disusun dengan memperhatikan ketentuan dan kebijakan yang berlaku. Titik Lokasi ; 1. Ruangan Sekretaris dan Staf; 2. Ruangan Bagian Umum; 3. Ruangan Bagian Keuangan; 4. Ruangan Bagian Risdang; 5. Ruangan Anggaran dan Pengawasan; 6. Ruangan Bagian Bendahara Aset; 7. Loby depan DPRD; 8. Ruangan Bagian Humas; 9. Ruangan Pimpinan DPRD dan Staf; 10. Ruangan Komisi-komisi DPRD; 11. Lorong-lorong Ruangan Fraksi-frkasi DPRD; 12. Ruangan Rapat Banmus; 13. Ruangan Rapat Banggar; 14. Ruangan Rapat Paripurna; 15. Ruangan Bapemperda; 16. Ruangan Fraksi PDI-Perjuangan; 17. Ruangan Fraksi Golkar.', 'Internet 300 Mbps, Back up 350 Mbps selama 1 (satu) Tahun; Channel TV Kabel 4 x 12 bulan; Layanan Dedicated dengan Bandwidth ratio CIR (Committed Information Rate) 1:1 Upload dan Download Simetris, Mendapatkan IP Publik, Semua Akses Port Terbuka, Koneksi Akhir Menggunakan Ethernet RJ45, Support Layanan dan dukungan Pelanggan 7X24 Jam baik secara online maupun Engineering On Site. Tersedianya Redundancy atau backup link, Tersedianya report utilisasi bandwidth yang dapat secara langsung baik link International (IX) maupun Domestik (IIX). Minimum Service Level Agreement (SLA) 99.9%. Setiap bulannya menerima laporan baik layanan jaringan maupun penggunaan bandwidth internet, dimana laporan terdiri dari system trouble ticketing, contact service dan eskalasi prosedur penanganan masalah yang jelas. Media akses baik backbone maupun distribusi menggunakan Fiber Optik milik sendiri. Free user akses Networks Monitoring atau MRTG, Koneksi Upstream Internasional: NTT Internasional, Google Peering, Equinix Echange, Google Global Cache, Akamai Domestik, Direct Peering Open IXP dan IXP, Support Data; SLA 99.9%; Memiliki layanan channel TV Kabel', 113072640, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 60178);
