INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942696', 61942696, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Survey Kelaikan Bangunan - Arsitektur 1 - SAPS 1 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'January 2026', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a. Membuat rencana jadwal survei dan surat pemberitahuan survei bangunan gedung yang akan dilakukan pengawasan. b. Melakukan survei pengawasan bangunan gedung yang meliputi pendataan implementasi penerapan Kaidah Bangunan Gedung Hijau, tingkat pemakaian Konsumsi Energi, penerapan kaidah ramah disabilitas, penerapan Sumur Resapan Air Hujan, dan kondisi kelaikan konstruksi reklame pada bangunan Gedung masa penggunaan. c. Mengolah data, monitoring data dan mengarsipkan data hasil survei pengawasan bangunan. d. Melakukan penginputan data hasil survei ke dalam sistem Jakarta Satu. e. Membantu mereview penilaian teknis hasil pengawasan bangunan. f. Membuat laporan pelaksanaan hasil kegiatan pengawasan bangunan. g. Membuat laporan bulanan dan laporan akhir kegiatan sesuai jadwal yang sudah ditentukan. "', '"Pekerjaan Senior Assistant Professional Staff di Bidang Arsitektur meliputi: • Pendidikan minimal Sarjana S1 Arsitektur • Memiliki KTP dan NPWP • Memiliki pengalaman 0 - 3 tahun disertai bukti pengalaman kerja (diutamakan berpengalaman). • Mampu bekerja individual dan kelompok/tim. • Bersedia bekerja survei lapangan maupun kantor mampu mengoperasikan kendaraan roda 2 dan 4 disertai memiliki SIM A /C (opsional) • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan. • Bersedia ditempatkan di seluruh wilayah DKI Jakarta. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 60481);
