INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942388', 61942388, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Sekretariat TPA, TPT, Penilik - Facilitator 3 - TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 64735000, 'January 2026', 'APBD', 1, 1, '1 Paket', '"Fasilitator wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a) Melaksanakan fasilitasi seluruh kegiatan Sekretariat TPA, TPT Penilik b) Mengirim dokumen/ berkas permohonan kepada TPA dan TPT c) Membuat rencana/jadwal survei serta surat penugasan terhadap penilik d) Memfasilitasi penjadwalan kegiatan TPA serta hasil kegiatannya e) Menginventarisasi dan mengarsipkan dokumen hasil kegiatan TPA, TPT dan Penilik f) Mencatat dan mengarsipkan data hasil pelaksanaan permohonan pada SIMBG g) Membuat laporan pelaksanaan dan laporan pertanggungjawaban hasil kegiatan TPA h) Membuat laporan bulanan kegiatan Fasilitator "', '"Pekerjaan Facilitator meliputi: • Pendidikan minimal Sarjana (S1) semua jurusan dengan pengalaman kerja ≤ 4 tahun • Jika mempunyai pengalaman lebih dari yang dimaksud, maka harus bersedia mengikuti nilai honor yang telah ditetapkan • Memiliki KTP dan NPWP • Terbiasa bekerja dengan menggunakan komputer, cloud storage dan jaringan internet • Mampu bekerja individual dan dalam kelompok/ tim • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan. • Bersedia ditempatkan di wilayah Kota Administrasi Jakarta Selatan "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 61198);
