INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942211', 61942211, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Sekretariat TPA, TPT, Penilik - Facilitator 1 - TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 64735000, 'January 2026', 'APBD', 1, 1, '1 paket', '"Fasilitator wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a) Melaksanakan fasilitasi seluruh kegiatan Sekretariat TPA, TPT Penilik b) Mengirim dokumen/ berkas permohonan kepada TPA dan TPT c) Membuat rencana/jadwal survei serta surat penugasan terhadap penilik d) Memfasilitasi penjadwalan kegiatan TPA serta hasil kegiatannya e) Menginventarisasi dan mengarsipkan dokumen hasil kegiatan TPA, TPT dan Penilik f) Mencatat dan mengarsipkan data hasil pelaksanaan permohonan pada SIMBG g) Membuat laporan pelaksanaan dan laporan pertanggungjawaban hasil kegiatan TPA h) Membuat laporan bulanan kegiatan Fasilitator "', '"Pekerjaan Facilitator meliputi: • Pendidikan minimal Sarjana (S1) semua jurusan dengan pengalaman kerja ≤ 4 tahun • Jika mempunyai pengalaman lebih dari yang dimaksud, maka harus bersedia mengikuti nilai honor yang telah ditetapkan • Memiliki KTP dan NPWP • Terbiasa bekerja dengan menggunakan komputer, cloud storage dan jaringan internet • Mampu bekerja individual dan dalam kelompok/ tim • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan. • Bersedia ditempatkan di wilayah Kota Administrasi Jakarta Selatan "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 61363);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942715', 61942715, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Survey Kelaikan Bangunan - Arsitektur 2 - SAPS 2 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'January 2026', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a. Membuat rencana jadwal survei dan surat pemberitahuan survei bangunan gedung yang akan dilakukan pengawasan. b. Melakukan survei pengawasan bangunan gedung yang meliputi pendataan implementasi penerapan Kaidah Bangunan Gedung Hijau, tingkat pemakaian Konsumsi Energi, penerapan kaidah ramah disabilitas, penerapan Sumur Resapan Air Hujan, dan kondisi kelaikan konstruksi reklame pada bangunan Gedung masa penggunaan. c. Mengolah data, monitoring data dan mengarsipkan data hasil survei pengawasan bangunan. d. Melakukan penginputan data hasil survei ke dalam sistem Jakarta Satu. e. Membantu mereview penilaian teknis hasil pengawasan bangunan. f. Membuat laporan pelaksanaan hasil kegiatan pengawasan bangunan. g. Membuat laporan bulanan dan laporan akhir kegiatan sesuai jadwal yang sudah ditentukan. "', '"Pekerjaan Senior Assistant Professional Staff di Bidang Arsitektur meliputi: • Pendidikan minimal Sarjana S1 Arsitektur • Memiliki KTP dan NPWP • Memiliki pengalaman 0 - 3 tahun disertai bukti pengalaman kerja (diutamakan berpengalaman). • Mampu bekerja individual dan kelompok/tim. • Bersedia bekerja survei lapangan maupun kantor mampu mengoperasikan kendaraan roda 2 dan 4 disertai memiliki SIM A /C (opsional) • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan. • Bersedia ditempatkan di seluruh wilayah DKI Jakarta. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 61364);
