INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942591', 61942591, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Sekretariat TPA, TPT, Penilik - Sipil 2 - SAPS 6 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'January 2026', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a) Melakukan pemeriksaan bidang sipil kepada dokumen perizinan PBG/SLF yang diajukan pada sistem SIMBG b) Melakukan analisis struktur dan pembuatan nota penyelesaian administrasi pada bangunan eksisting untuk permohonan SLF c) Melakukan inspeksi bangunan gedung dalam tahap pelaksanaan konstruksi. d) Mengolah data, monitoring data dan mengarsipkan data hasil inspeksi. e) Membantu mereviu penilaian teknis hasil konsultasi dokumen permohonan/ konsultasi dan inspeksi f) Membuat laporan pelaksanaan hasil kegiatan penyelenggaraan bangunan g) Membuat laporan bulanan dan laporan akhir kegiatan sesuai jadwal yang sudah ditentukan "', '"""Pekerjaan Senior Assistant Professional Staff di Bidang Sipil meliputi: • Pendidikan minimal Sarjana S1 Sipil • Memiliki KTP dan NPWP • Memiliki pengalaman 0 - 3 tahun disertai bukti pengalaman kerja (diutamakan berpengalaman). • Mampu bekerja individual dan kelompok/tim. • Bersedia bekerja survei lapangan maupun kantor (untuk tenaga teknis). • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan. • Bersedia ditempatkan di seluruh wilayah DKI Jakarta."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 62440);
