INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62788101', 62788101, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Sosial Tenaga Kerja dan Transmigrasi', 'Belanja Jasa Aktivitas Sosial Pemerintah di dalam Panti untuk Lanjut Usia (87301) Penyedia Jasa Lainnya Orang Perseorangan Spesifikasi : D3, Pengalaman Kerja < 16 Tahun, Kategori A - UPT RPSLUT (1)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 37440000, 'January 2026', 'APBD', 1, 1, '12 bulan', '1. Membantu kebutuhan kelayan sebelum atau saat tidur; 2. Mempersiapkan peralatan mandi kelayan; 3. Membaca dan mencermati buku laporan setiap pergantian shift; 4. Bertanggung jawab atas pembagian makan dan minum kelayan; 5. Bertanggung jawab atas penyiapan peralatan makan dan minum pagi kelayan; 6. Bertanggung jawab atas pembagian snack dan minum klien; 7. Memberikan masukan nutrisi kepada klien; 8. Bertanggung jawab atas kebersihan dan kerapihan peralatan makan; 9. Bertanggung jawab serta menjaga kebersihan dan kerapihan wisma dan lingkungan sekitar kelayan; 10. Bertanggung jawab membantu klien dalam pemenuhan kebutuhan sehari-hari (seperti membantu: berpakaian,BAB,BAK); 11. Mengobservasi keadaan kelayan dengan cara datang setiap-tiap wisma; 12. Mengantar atau menjemput klien saat pemeriksaan klinik 13 Bertanggungjawab dalam kolaborasi pemberian obat oral, tetes, topikal, vekal; 14. Melakukan tindakan perawatan luka bila diperlukan; 15. Mengisi pemberian terapi dicatatan rekam medis klien; 16. Bertanggung jawab pakaian kotor klien yang betrest/tidak mandiri; 17. Bertanggung jawab kebersihan dan kerapihan klien; 18. Memandikan klien yang betrest/ tidak mandi/keterbatasan serta membersihkan dan merapikan tempat tidurnya; 19. Membantu mobilisasi klien dengan keterbatasan klien; 20. Melakukan pemeriksaan kesehatan saat klinik & posyandu (menimbang BB, TB, serta tanda-tanda vital : tensi darah, suhu, pernafasan, nadi); 21. Melakukan perawatan jenazah serta memandikan dan mengkafani mayat; 22. Melaksanakan tugas yang diperintahkan oleh atasan; 23. Melaporkan hasil pekerjaan kepada atasan.', 'D3, Pengalaman Kerja < 16 Tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 62707);
