INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61951887', 61951887, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Pemeliharaan Kendaraan Roda 4 (Empat) Operasional Untuk Kegiatan Pemeliharaan Kendaraan Dinas Operasional Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 222000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6.0 UT', 'Pekerjaan ini berupa penyediaan layanan pemeliharaan kendaraan roda empat operasional yang digunakan dalam menunjang kegiatan kedinasan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 dengan volume sebanyak 6 (enam) unit untuk jangka waktu 1 (satu) Tahun Anggaran. Kegiatan ini bertujuan menjaga kendaraan dinas tetap dalam kondisi optimal, aman, dan layak jalan sehingga dapat mendukung pelaksanaan tugas serta operasional kedinasan secara efektif dan berkelanjutan.', 'Pekerjaan ini memiliki spesifikasi minimal Pemeliharaan meliputi servis rutin dan pemeliharaan lanjutan sesuai rekomendasi teknis pabrikan kendaraan operasional. Perawatan mencakup sistem mesin, transmisi, kelistrikan, pendingin udara, pengereman, suspensi, dan komponen pendukung lainnya. Termasuk penggantian oli mesin, oli transmisi, petunjuk servis lainnya, filter oli, filter udara, filter AC/kabin, coolant, minyak rem, busi, serta komponen habis pakai lain sesuai kondisi kendaraan. Seluruh suku cadang wajib menggunakan komponen asli (original spare part) atau sesuai standar pabrikan kendaraan operasional yang digunakan. Melakukan pengecekan ban kendaraan, tekanan angin, lampu penerangan, wiper, sistem keamanan, dan fungsi keselamatan lainnya. Kendaraan dibersihkan bagian dalam dan luar setelah proses servis atau perbaikan selesai. Dokumentasi pekerjaan wajib disusun dalam bentuk laporan yang memuat hasil pemeriksaan, tindakan yang dilakukan, daftar komponen yang diganti, dan rekomendasi pemeliharaan lanjutan. Garansi layanan diberikan untuk pekerjaan servis dan komponen yang diganti sesuai ketentuan pabrikan atau minimal selama 3 bulan setelah pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 63441);
