INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61951304', 61951304, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Penyusunan Ketentuan/Perencanaan Penataan Ruang  Senior Assistant Professional Staff - Arsitektur 02', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 75075000, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Pekerjaan yang dilakukan meliputi: 1. Pengumpulan data dan informasi baik data primer maupun sekunder; 2. Pengkajian dan analisa terhadap: 3. Penyusunan konsep perencanaan yang meliputi hasil analisis dan gagasan, pengaturan intensitas pemanfaatan ruang, tata bangunan, sistem sirkulasi, pengaturan sistem parkir, pengaturan ruang terbuka hijau serta tata informasi; 4. Penyusunan skenario penataan kawasan dan dituangkan dalam bentuk indikasi program; 5. Pembuatan peta-peta geospasial yang menunjang untuk laporan; 6. Menyusun bahan dalam rangka pengkajian penataan kegiatan dalam pemanfaatan ruang sesuai dengan lingkup Suku Dinas Cipta Karya, Tata Ruang dan Pertanahan Kota Administrasi. "', '"Pekerjaan Senior Assistant Professional Staff di bidang Arsitektur, meliputi: (1) Pendidikan Minimal S1 dari Universitas Negeri/ Swasta; (2) Pengalaman Kerja 0-3 tahun di bidang urban design, perencanaan wilayah perkotaan, penataan kawasan dan atau pekerjaan sejenis; (3) Memiliki ide dan gagasan tentang urban design, perencanaan wilayah perkotaan, penataan kawasan dan atau pekerjaan sejenis; (4) Menguasai Autocad, SketchUp, program rendering, Ms. Office, memiliki kemampuan membuat animasi 3D/desain grafis/ visualisasi; (5) Menguasai program lain yang menunjang pekerjaan (3ds Max, Adobe Photoshop, Illustrator, Coreldraw, Audesk Maya, Lumion, Blender, Sketch Up, Adobe Photoshop, ErMapper, SPSS, DropBox/One Box, dll.) dan program lain yang menunjang pekerjaan; "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 63921);
