INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61951780', 61951780, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Pemeliharaan Kendaraan Roda 4 (empat) Eselon II Untuk Mendukung Kegiatan Pemeliharaan Peralatan dan Mesin Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 210000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '5.0 UT', 'Pekerjaan ini meliputi pelaksanaan layanan pemeliharaan kendaraan roda empat sebanyak 5 unit untuk satu tahun anggaran yang digunakan oleh Pejabat Eselon II dalam rangka menunjang kelancaran operasional dan kegiatan kedinasan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Pelaksanaan kegiatan dilakukan secara berkala sesuai standar perawatan kendaraan resmi pemerintah, mencakup perawatan preventif dan korektif untuk menjaga kondisi kendaraan tetap layak, aman, dan siap digunakan.', 'pekerjaan ini memiliki spesifikasi minimal Pemeliharaan dilakukan secara berkala sesuai standar rekomendasi pabrikan kendaraan. Ruang lingkup mencakup perawatan mesin, transmisi, suspensi, sistem kelistrikan, sistem AC, sistem pengereman, serta pemeriksaan komponen keselamatan. Pelaksanaan termasuk penggantian oli mesin, oli transmisi, filter oli, filter udara, filter kabin, busi, coolant, minyak rem, dan material habis pakai sesuai kebutuhan teknis. Suku cadang yang digunakan wajib asli (original spare part) sesuai merek dan tipe kendaraan dinas yang dirawat. Penyedia wajib melakukan pemeriksaan kondisi ban, tekanan angin, wiper, lampu, sistem keselamatan, dan fungsi komponen lainnya. Termasuk layanan pembersihan kendaraan setelah pemeliharaan selesai (interior dan eksterior). Penyedia wajib menyerahkan laporan hasil pemeliharaan, termasuk daftar komponen yang diganti beserta dokumentasi pendukung. Pekerjaan dilengkapi jaminan layanan dan garansi atas hasil pekerjaan serta suku cadang yang digunakan sesuai ketentuan produsen atau minimal 3 bulan setelah pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 64133);
