INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61946645', 61946645, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Belanja Jasa Tenaga Informasi dan Teknologi-Paruh Waktu - Penyediaan Jasa Pelayanan Umum Kantor', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Timur, Mojokerto (Kota)', 247200000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Belanja Jasa Tenaga Informasi dan Teknologi-Paruh Waktu - Penyediaan Jasa Pelayanan Umum Kantor 1. Bagian Pengembangan dan Pelayanan Telecenter SMK/SMA : 3 orang 2. Manager Telecenter S1 : 1 orang 3. Operator PPID dan Pengaduan DI/DII/DIII/S1 Terapan : 1 orang 4. Sekretaris Telecenter SMK/SMA : 1 orang 5. Reporter DI/DII/DIII/S1 Terapan : 2 orang', 'Bagian Pengembangan dan Pelayanan Telecenter mempunyai tugas : 1. Mengkoordinasi dan menyiapkan segala keperluaan pelaksanaan kegiatan operasional Telecenter; 2. Menyediakan pelayanan akses informasi bagi masyarakat dan memfasilitasi pemberdayaan masyarakat dibidang Teknologi Informasi dan Komunikasi (TIK); 3. Menjamin keamanan dan pemeliharaan peralatan atau sarana dan prasarana Telecenter palapa serta memanfaatkanya secara berdayaguna untuk pemberdayaan masyarakat; 4. Menyusun dan melaksanakan rencana kerja Telecenter yang mengarah pada peningkatan kesejateraan masyarakat Kota Mojokerto; 5. Melakukan pendampingan kepada kolompok – kelompok masyarakat dalam memanfaatkan fasilitas Telecenter sebagai sumber informasi dalam upaya meningkatkan kesejahteraan; 6. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang ,Kepala Seksi, dan Kepala Sub Bagian pada Dinas Komunikasi dan Informatika Kota Mojokerto; 7. Melaporkan hasil kegiatan pada akhir bulan Manajer Telecenter mempunyai tugas : 1. Mengkoordinasi dan menyiapkan segala keperluaan pelaksanaan kegiatan operasional Telecenter; 2. Menyediakan pelayanan akses informasi bagi masyarakat dan memfasilitasi pemberdayaan masyarakat dibidang Teknologi Informasi dan Komunikasi (TIK); 3. Menjamin keamanan dan pemeliharaan peralatan atau sarana dan prasarana Telecenter palapa serta memanfaatkanya secara berdayaguna untuk pemberdayaan masyarakat; 4. Menyusun dan melaksanakan rencana kerja Telecenter yang mengarah pada peningkatan kesejateraan masyarakat Kota Mojokerto; 5. Melakukan pendampingan kepada kolompok – kelompok masyarakat dalam memanfaatkan fasilitas Telecenter sebagai sumber informasi dalam upaya meningkatkan kesejahteraan; 6. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang ,Kepala Seksi, dan Kepala Sub Bagian pada Dinas Komunikasi dan Informatika Kota Mojokerto; 7. Melaporkan hasil kegiatan pada akhir bulan Operator PPID mempunyai tugas 1. Melaksanakan Pelayanan Permohonan Informasi Data dan proses penyimpanan, pendokumentasian, penyediaan dan pelayanan Informasi Publik lainnya 2. Menyiapkan dokumen untuk membantu PPID dalam melaksanakan pengujian konsekuensi atas Informasi Publik 3. Membuat, mengelola, memelihara, dan/atau memutakhirkan Daftar Informasi Publik 4. Menghimpun Informasi Publik dari seluruh unit kerja dan/atau satuan kerja 5. Membuat laporan layanan Informasi Publik 6. Melakukan ceklis kelengkapan Informasi Publik 7. Melaksanakan tugas kedinasan lain yang diperintahkan oleh kepala Dinas, Sekretaris, Kepala Bidang, Kepala seksi dan kepala sub bagian ( SIRUP, SIPD, Pengadaaan Barang Jasa DLL terkait Administrasi Perkantoran) Operator Pengaduan Layanan mempunyai tugas : 1. Melakukan Kegiatan Pelayanan Pengaduan, Aspirasi, Permohan Informasi dan Pengelolaan Layanan Teknis lainnya 2. Berkoordinasi dengan Pejabat Penghubung terkait Pengelolaan Pengaduan secara langsung atau tidak langsung. 3. Menjalankan fungsi sebagai admin instansi dan admin pejabat penghubung yang mengelola Pengaduan Pelayanan Publik melalui SP4N. 4. Menjadi petugas pelayanan pengaduan untuk membantu dalam proses penerimaa, pencatatan, verifikasi (berupa data maupun cek lokasi) dan distribusi Pengaduan. 5. Mendistribusikan Pengaduan kepada Pejabat Penghubung . 6. Memberikan tanggapan awal Pengaduan berdasarkan frequently asked question. 7. Melakukan Monitoring dan evaluasi tindak lanjut penyelesaian Pengaduan. 8. Membuat Laporan bulanan Pengaduan 9. Mengelola Sosial Media Pengaduan. 10. Menindaklanjuti Pengaduan dengan cermat, cepat, dan tuntas. 11. Memberikan Respon dan tanggapan sesuai substansi pengaduan. 12. Memberikan tanggapan ulang apabila diperlukan hingga penanganan pengaduan Sekretaris Telecenter mempunyai tugas : 1. Mengkoordinasi dan menyiapkan segala keperluaan pelaksanaan kegiatan operasional Telecenter; 2. Menyediakan pelayanan akses informasi bagi masyarakat dan memfasilitasi pemberdayaan masyarakat dibidang Teknologi Informasi dan Komunikasi (TIK); 3. Menjamin keamanan dan pemeliharaan peralatan atau sarana dan prasarana Telecenter palapa serta memanfaatkanya secara berdayaguna untuk pemberdayaan masyarakat; 4. Menyusun dan melaksanakan rencana kerja Telecenter yang mengarah pada peningkatan kesejateraan masyarakat Kota Mojokerto; 5. Melakukan pendampingan kepada kolompok – kelompok masyarakat dalam memanfaatkan fasilitas Telecenter sebagai sumber informasi dalam upaya meningkatkan kesejahteraan; 6. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang ,Kepala Seksi, dan Kepala Sub Bagian pada Dinas Komunikasi dan Informatika Kota Mojokerto; 7. Melaporkan hasil kegiatan pada akhir bulan Reporter mempunyai Tugas : 1. Melakukan riset, mengumpulkan data dan peliputan terkait kegiatan Kepala Daerah, event Pemerintah Kota, serta capaian Pemerintah Kota Mojokerto. 2. Melakukan wawancara dan memverifikasi Informasi. 3. Menulis dan menyusun narasi. 4. Melakukan siaran langsung jika diperlukan 5. Memantau perkembangan isu lokal maupun nasional', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 64602);
