INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62790993', 62790993, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Penyusunan Buku Informasi Perkeretaapian Tahun 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Menyediakan media informasi seputar bidang perkeretaapian yang handal, lengkap dan mutakhir bagi kalangan internal maupun eksternal Direktorat Jenderal Perkeretaapian', '1. Pengumpulan/updating data dan informasi terkait dengan bidang perkeretaapian yang terkini guna mendukung penyajian data informasi dalam Buku Informasi Perkeretaapian, yang meliputi: a. Rencana, program dan capaian pembangunan perkeretaapian termasuk profil proyek strategis; b. Gambaran jaringan jalur kereta api dan layanan perkeretaapian per wilayah kerja Balai; c. Gambaran kondisi sarana dan prasarana perkeretaapian; d. Data kinerja perkeretaapian bidang prasarana, lalu lintas dan angkutan kereta api, sarana, SDM dan keselamatan perkeretaapian; e. Informasi teknis lainnya yang terkait perkeretaapian. 2. Pengelolaan dan updating data prasarana, sarana, lalu lintas dan angkutan kereta api serta keselamatan perkeretaapian berbasis geospasial. 3. Pengelolaan dan updating data statistik prasarana, sarana, lalu lintas dan angkutan kereta api serta keselamatan termasuk benchmarking kinerja perkeretaapian pada lingkup internasional. 4. Penyusunan Buku Informasi/Ensiklopedia Perkeretaapian dengan konten umum dan lengkap menyerupai format majalah dengan tampilan menarik dan full-grafis termasuk media informasi digital executive summary. 5. Lokasi pemberi kerja di Jakarta, dengan ruang lingkup pelaksanaan survei di wilayah Bandung, Jawa Barat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 67238);
