INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62789636', 62789636, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual Penyusunan Kajian Model Standar Pelayanan Minimal (SPM) Berdasarkan Tipologi Wilayah Direktorat Pemerintahan, Keuangan Daerah Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99990000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Melakukan inventarisasi dan identifikasi data, informasi, serta konsep pelaporan perkembangan penerapan SPM per daerah; 2. Menyusun konsep pemetaan dan visualisasi data terkait penerapan SPM daerah; 3. Menyusun konsep instrumen pelaksanaan monitoring dan evaluasi penerapan SPM berbasis tipologi wilayah di daerah; 4. Melakukan analisis data kualitatif dalam proses perencanaan dan penerapan SPM di daerah berbasis tipologi wilayah; 5. Melakukan analisis terkait pelaksanaan SPM di daerah dengan menghimpun masukan, mengidentifikasi kendala, serta merumuskan solusi dan langkah-langkah untuk tahap berikutnya. 6. Melakukan analisis substansi Revisi Undang-Undang No. 23 tahun 2014 tentang Pemerintahan Daerah, khususnya terkait SPM dengan menghimpun masukan, serta merumuskan konsep rekomendasi sesuai peraturan perundang-undangan. 7. Menyusun laporan akhir Model Standar Pelayanan Minimal (SPM) Berdasarkan Tipologi Wilayah. 8. Melaksanakan penugasan-penugasan lain yang ditugaskan oleh pimpinan dalam lingkup penataan desentralisasi dan otonomi daerah.', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP) 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Pengembangan Wilayah/ Perencanaan Wilayah dan Kota/Manajemen Kebijakan Publik; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 5. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan; 6. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% nilai total HPS; 7. Memiliki pengalaman bidang monitoring dan evaluasi mengenai isu SPM minimal 2 (dua) tahun yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 8. Memiliki pengalaman dibidang perencanaan atau evaluasi mengenai isu kebijakan desentralisasi dan otonomi daerah terutama pada bidang SPM minimal 2 (dua) tahun dalam kurun waktu 4 (empat) tahun terakhir yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 9. Menguasai software pengelolaan data dan informasi geospasial dibuktikan dengan sertifikat/laporan/presentasi formal memuat pengolahan data dengan menggunakan software GIS (ArcGIS/QGIS);', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 67972);
