INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62790081', 62790081, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'In House Consultant Bidang Perencanaan Perkeretaapian', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1600000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan analisa dan evaluasi terhadap rumusan perencanaan subsektor perkeretaapian termasuk analisa dan evaluasi terhadap dokumen penilaian kinerja Ditjen Perkeretaapian', '1. Melakukan analisa dan evaluasi terhadap rumusan dokumen perencanaan jangka pendek, jangka menengah dan jangka panjang subsektor perkeretaapian; 2. Melakukan analisa terhadap indikasi proporsi kebutuhan biaya program pembangunan tahunan yang tertuang dalam Rencana Kerja Anggaran; 3. Mengidentifikasi kewajaran harga satuan dalam usulan kebutuhan biaya program pembangunan; 4. Mengidentifikasi sumber-sumber pendanaan alternatif guna memenuhi kebutuhan pembiayaan pembangunan program perkeretaapian; 5. Menyusun format pelaporan dan metode evaluasi terhadap pelaksanaan program pembangunan berdasarkan evaluasi pencapaian fisik maupun pencapaian anggaran; 6. Melakukan analisa dan evaluasi terhadap capaian kinerja Ditjen Perkeretaapian; 7. Menyusun format penyajian laporan yang dapat digunakan baik oleh pengguna pada level teknis/pelaksana maupun pengguna pada level pengambil keputusan; 8. Menyusun rekomendasi terhadap strategi perencanaan yang akan datang berdasarkan hasil evaluasi realisasi rencana program pada tahun berjalan; 9. Mendukung tugas pengelolaan dan pemantauan sistem informasi termasuk memberikan rekomendasi teknis terhadap penyelenggaraan sistem informasi; 10. Mendukung penyiapan bahan pimpinan dan penugasan lainnya yang berkaitan dengan penyiapan desain/logo/template/paparan/dll sesuai kebutuhan organisasi (Desain Grafis); 11. Mendukung penyiapan bahan pimpinan dan penugasan lainnya yang berkaitan dengan penyiapan video, animasi, grafis, atau presentasi sesuai kebutuhan organisasi; 12. Lokasi pekerjaan di Jakarta, dengan ruang lingkup pelaksanaan kerja di wilayah DKI Jakarta, khususnya di Bagian Perencanaan Direktorat Jenderal Perkeretaapian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 68284);
