INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146081', 62146081, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Bahan Penunjang Pengendalian Vektor', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 15694000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '( 1, PT, @ 15694000 )', '1. Bahan Penunjang Pengendalian Vektor ( 1, PT, @ 15694000 );', 'Pekerjaan ini meliputi penyediaan berbagai bahan pendukung habis pakai yang diperlukan untuk kelancaran kegiatan pengendalian serangga dan hewan penular penyakit di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pekerjaan mencakup penyediaan bahan operasional seperti cairan pelarut insektisida, bahan penarik/umpan vektor, serta perlengkapan perlindungan diri petugas lapangan dan wadah penampung limbah medis hasil kegiatan. Spesifikasi teknis mewajibkan seluruh bahan yang disediakan dalam kondisi baru, memiliki masa kedaluwarsa yang panjang, dan memenuhi standar keamanan lingkungan guna menjamin efektivitas pemutusan rantai penularan penyakit. Pengadaan ini bertujuan untuk memastikan ketersediaan logistik yang memadai sehingga kegiatan intervensi kesehatan seperti penyemprotan dan pemberantasan sarang nyamuk dapat terlaksana secara tepat waktu, efektif, dan sesuai dengan target kinerja instansi sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 68339);
