INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61956081', 61956081, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Pemeliharaan Kendaraan Roda 2 (dua) Untuk Kegiatan Pemeliharaan Kendaraan Dinas Operasional Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 14880000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3.0 UT', 'Pekerjaan ini mencakup penyediaan layanan pemeliharaan kendaraan roda dua yang digunakan sebagai kendaraan dinas operasional pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 dengan volume sebanyak 3 UT (Unit) untuk jangka waktu 1 (satu) tahun. Tujuan pekerjaan ini adalah menjaga kondisi kendaraan agar tetap layak digunakan, aman, dan terpelihara dengan baik sehingga dapat mendukung kelancaran kegiatan operasional kedinasan secara efektif dan berkesinambungan.', 'Pekerjaan ini memiliki spesifikasi minimal Pemeliharaan dilakukan sesuai jadwal servis berkala berdasarkan rekomendasi teknis dari pabrikan kendaraan roda dua. Perawatan mencakup komponen mesin, sistem rem, suspensi, aki, kelistrikan, ban, sistem pendinginan, dan komponen penunjang keselamatan berkendara lainnya. Termasuk penggantian oli mesin, filter oli (jika ada), busi, minyak rem, coolant, gear oil, kampas rem, dan komponen habis pakai lainnya sesuai kondisi teknis. Penggunaan suku cadang wajib orisinal (original spare part) atau yang sesuai standar resmi pabrikan kendaraan roda dua. melakukan pemeriksaan tekanan ban, fungsi lampu, klakson, indikator panel kendaraan, kaca spion, serta komponen keselamatan lainnya. Kendaraan dibersihkan secara menyeluruh (exterior dan area mesin) setelah pekerjaan pemeliharaan selesai, menyusun laporan hasil servis yang memuat daftar pekerjaan, kondisi kendaraan sebelum dan sesudah pemeliharaan, serta daftar suku cadang yang diganti. Layanan perbaikan dan penggantian suku cadang diberikan garansi sesuai ketentuan pabrikan atau minimal 3 bulan setelah pekerjaan dilakukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 69206);
