INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201057', 63201057, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Persiapan Bahan dan Alat Pelaksanaan Survei Faktor Risiko Penyakit Pes dan Leptospirosis', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 13806000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Belanja Bahan;', 'Pekerjaan ini meliputi penyediaan sarana logistik, bahan habis pakai, dan penyiapan peralatan teknis yang diperlukan sebelum dimulainya kegiatan survei lapangan di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pekerjaan mencakup pengadaan perlengkapan pelindung diri (seperti sarung tangan dan masker), bahan sterilisasi alat, wadah penyimpanan sampel (seperti plastik klip dan botol spesimen), serta penyiapan/perbaikan ringan komponen alat tangkap hewan penular agar berfungsi optimal saat digunakan. Spesifikasi teknis difokuskan pada pemenuhan kualitas bahan yang standar dan aman bagi petugas guna mendukung proses pengambilan sampel spesimen (seperti pinjal dan darah) tanpa risiko kontaminasi. Pengadaan ini bertujuan untuk menjamin kesiapan seluruh perangkat surveilans sebelum tim turun ke lapangan, sehingga proses identifikasi faktor risiko penyakit Pes dan Leptospirosis dapat terlaksana secara sistematis, akurat, dan sesuai dengan standar kesehatan kerja sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 69440);
